def sqlite_wal_reset_fix_available() -> bool:
    version = sqlite3.sqlite_version_info
    return (
        version >= (3, 51, 3)
        or (3, 50, 7) <= version < (3, 51, 0)
        or (3, 44, 6) <= version < (3, 45, 0)
    )


SCHEMA_V1_SQL = """
CREATE TABLE IF NOT EXISTS store_metadata (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS missions (
    mission_id TEXT PRIMARY KEY,
    context_json TEXT NOT NULL,
    context_hash TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK (revision >= 0),
    head_hash TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS mission_events (
    mission_id TEXT NOT NULL,
    sequence INTEGER NOT NULL CHECK (sequence > 0),
    event_id TEXT NOT NULL,
    event_type TEXT NOT NULL,
    actor_profile_id TEXT NOT NULL,
    event_timestamp TEXT NOT NULL,
    event_json TEXT NOT NULL,
    previous_hash TEXT NOT NULL,
    entry_hash TEXT NOT NULL,
    stored_at TEXT NOT NULL,
    PRIMARY KEY (mission_id, sequence),
    UNIQUE (mission_id, event_id),
    FOREIGN KEY (mission_id) REFERENCES missions(mission_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS mission_events_by_id
ON mission_events (mission_id, event_id);

CREATE TABLE IF NOT EXISTS approval_queue (
    approval_id TEXT PRIMARY KEY,
    mission_id TEXT NOT NULL,
    proposal_id TEXT NOT NULL,
    proposal_hash TEXT NOT NULL,
    proposer_profile_id TEXT NOT NULL,
    executor_profile_id TEXT NOT NULL,
    action_tier TEXT NOT NULL,
    scope_reference TEXT NOT NULL,
    purpose TEXT NOT NULL CHECK (purpose = 'simulation'),
    submitted_at TEXT NOT NULL,
    review_expires_at TEXT NOT NULL,
    status TEXT NOT NULL
        CHECK (status IN ('pending', 'approved', 'denied', 'consumed', 'revoked')),
    version INTEGER NOT NULL CHECK (version >= 1),
    submit_key_hash TEXT NOT NULL,
    submit_request_hash TEXT NOT NULL,
    decision_actor_profile_id TEXT,
    decision_at TEXT,
    decision_code TEXT,
    decision_reason TEXT,
    decision_key_hash TEXT,
    decision_request_hash TEXT,
    decision_event_id TEXT,
    authorization_event_id TEXT,
    authorization_expires_at TEXT,
    simulation_key_hash TEXT,
    simulation_id TEXT,
    UNIQUE (mission_id, proposal_id),
    FOREIGN KEY (mission_id, proposal_id)
        REFERENCES mission_events(mission_id, event_id) ON DELETE RESTRICT,
    FOREIGN KEY (mission_id, authorization_event_id)
        REFERENCES mission_events(mission_id, event_id) ON DELETE RESTRICT,
    FOREIGN KEY (mission_id, decision_event_id)
        REFERENCES mission_events(mission_id, event_id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS simulation_receipts (
    mission_id TEXT NOT NULL,
    simulation_id TEXT NOT NULL,
    approval_id TEXT NOT NULL,
    proposal_id TEXT NOT NULL,
    authorization_id TEXT NOT NULL,
    receipt_json TEXT NOT NULL,
    receipt_hash TEXT NOT NULL,
    recorded_at TEXT NOT NULL,
    PRIMARY KEY (mission_id, simulation_id),
    UNIQUE (approval_id),
    FOREIGN KEY (approval_id)
        REFERENCES approval_queue(approval_id) ON DELETE RESTRICT,
    FOREIGN KEY (mission_id, proposal_id)
        REFERENCES mission_events(mission_id, event_id) ON DELETE RESTRICT,
    FOREIGN KEY (mission_id, authorization_id)
        REFERENCES mission_events(mission_id, event_id) ON DELETE RESTRICT
);
"""

