SCHEMA_V21_ADDITIONS_SQL = """
CREATE TABLE execution_terminal_custody_commits (
    custody_plan_id TEXT PRIMARY KEY
        CHECK (
            length(custody_plan_id) = 36
            AND substr(custody_plan_id, 1, 4) = 'ECT-'
            AND substr(custody_plan_id, 5) NOT GLOB '*[^0-9A-F]*'
        ),
    custody_plan_sha256 TEXT NOT NULL UNIQUE,
    mission_id TEXT NOT NULL,
    work_item_id TEXT NOT NULL,
    transfer_kind TEXT NOT NULL
        CHECK (transfer_kind IN ('ownership_handoff', 'work_cancellation')),
    terminal_kind TEXT NOT NULL
        CHECK (terminal_kind IN ('completed', 'failed_closed_timeout')),
    outcome_id TEXT NOT NULL UNIQUE,
    outcome_sha256 TEXT NOT NULL,
    outcome_authentication_id TEXT UNIQUE,
    outcome_authentication_sha256 TEXT,
    request_authentication_id TEXT NOT NULL UNIQUE,
    request_authentication_sha256 TEXT NOT NULL,
    transfer_request_id TEXT NOT NULL UNIQUE,
    transfer_request_sha256 TEXT NOT NULL,
    source_session_disposition TEXT NOT NULL
        CHECK (
            source_session_disposition IN (
                'revoked_unavailable',
                'fenced_pending_recovery'
            )
        ),
    target_session_disposition TEXT NOT NULL
        CHECK (
            target_session_disposition IN (
                'eligible_after_atomic_commit',
                'blocked_never_activated',
                'not_applicable'
            )
        ),
    recovery_required INTEGER NOT NULL
        CHECK (recovery_required IN (0, 1)),
    participant_count INTEGER NOT NULL
        CHECK (participant_count BETWEEN 2 AND 4),
    custody_plan_json TEXT NOT NULL
        CHECK (
            length(custody_plan_json) > 0
            AND json_valid(custody_plan_json)
            AND json_type(custody_plan_json, '$') = 'object'
        ),
    committed_at TEXT NOT NULL CHECK (length(committed_at) > 0),
    UNIQUE (mission_id, work_item_id, transfer_request_id),
    CHECK (json_extract(custody_plan_json, '$.custody_plan_id') = custody_plan_id),
    CHECK (
        json_extract(custody_plan_json, '$.custody_plan_sha256')
            = custody_plan_sha256
    ),
    CHECK (json_extract(custody_plan_json, '$.mission_id') = mission_id),
    CHECK (json_extract(custody_plan_json, '$.work_item_id') = work_item_id),
    CHECK (json_extract(custody_plan_json, '$.transfer_kind') = transfer_kind),
    CHECK (json_extract(custody_plan_json, '$.terminal_kind') = terminal_kind),
    CHECK (
        json_extract(custody_plan_json, '$.terminal_outcome.outcome_id')
            = outcome_id
    ),
    CHECK (
        json_extract(custody_plan_json, '$.terminal_outcome.outcome_sha256')
            = outcome_sha256
    ),
    CHECK (
        json_extract(
            custody_plan_json,
            '$.outcome_authentication.authentication_id'
        ) IS outcome_authentication_id
    ),
    CHECK (
        json_extract(
            custody_plan_json,
            '$.outcome_authentication.authentication_sha256'
        ) IS outcome_authentication_sha256
    ),
    CHECK (
        json_extract(
            custody_plan_json,
            '$.request_authentication.authentication_id'
        ) = request_authentication_id
    ),
    CHECK (
        json_extract(
            custody_plan_json,
            '$.request_authentication.authentication_sha256'
        ) = request_authentication_sha256
    ),
    CHECK (
        json_extract(custody_plan_json, '$.transfer_request.request_id')
            = transfer_request_id
    ),
    CHECK (
        json_extract(custody_plan_json, '$.transfer_request.request_sha256')
            = transfer_request_sha256
    ),
    CHECK (
        json_extract(custody_plan_json, '$.source_session_disposition')
            = source_session_disposition
    ),
    CHECK (
        json_extract(custody_plan_json, '$.target_session_disposition')
            = target_session_disposition
    ),
    CHECK (
        json_extract(custody_plan_json, '$.recovery_required')
            = recovery_required
    ),
    CHECK (
        json_array_length(custody_plan_json, '$.participant_authentications')
            = participant_count
    ),
    CHECK (
        json_array_length(custody_plan_json, '$.assertion_consumption_order')
            = participant_count
    ),
    CHECK (
        (terminal_kind = 'completed'
            AND substr(outcome_id, 1, 4) = 'ETC-'
            AND outcome_authentication_id IS NULL
            AND outcome_authentication_sha256 IS NULL
            AND recovery_required = 0)
        OR
        (terminal_kind = 'failed_closed_timeout'
            AND substr(outcome_id, 1, 4) = 'ETD-'
            AND substr(outcome_authentication_id, 1, 4) = 'ETA-'
            AND outcome_authentication_sha256 IS NOT NULL
            AND recovery_required = 1)
    ),
    FOREIGN KEY (mission_id)
        REFERENCES missions(mission_id) ON DELETE RESTRICT
);

CREATE TABLE execution_terminal_custody_participants (
    custody_plan_id TEXT NOT NULL,
    participant_index INTEGER NOT NULL CHECK (participant_index >= 0),
    mission_id TEXT NOT NULL,
    role TEXT NOT NULL
        CHECK (
            role IN (
                'control_plane_requester',
                'source_worker',
                'target_worker',
                'independent_control'
            )
        ),
    authentication_id TEXT NOT NULL UNIQUE,
    authentication_sha256 TEXT NOT NULL,
    profile_id TEXT NOT NULL,
    issuer TEXT NOT NULL,
    assertion_id TEXT NOT NULL,
    assertion_sha256 TEXT NOT NULL,
    operation TEXT NOT NULL,
    operation_intent_sha256 TEXT NOT NULL,
    policy_sha256 TEXT NOT NULL,
    scope_grant_id TEXT NOT NULL,
    scope_grant_sha256 TEXT NOT NULL,
    committed_at TEXT NOT NULL CHECK (length(committed_at) > 0),
    PRIMARY KEY (custody_plan_id, participant_index),
    UNIQUE (issuer, assertion_id),
    FOREIGN KEY (custody_plan_id)
        REFERENCES execution_terminal_custody_commits(custody_plan_id)
        ON DELETE RESTRICT,
    FOREIGN KEY (issuer, assertion_id, mission_id)
        REFERENCES principal_assertion_uses(issuer, assertion_id, mission_id)
        ON DELETE RESTRICT
);

CREATE TRIGGER execution_terminal_custody_participant_guard
BEFORE INSERT ON execution_terminal_custody_participants
WHEN NOT EXISTS (
    SELECT 1
    FROM execution_terminal_custody_commits AS custody
    JOIN principal_assertion_uses AS assertion_use
      ON assertion_use.issuer = NEW.issuer
     AND assertion_use.assertion_id = NEW.assertion_id
     AND assertion_use.mission_id = NEW.mission_id
    JOIN principal_assertion_effects AS effect
      ON effect.issuer = assertion_use.issuer
     AND effect.assertion_id = assertion_use.assertion_id
     AND effect.effect_index = 1
    WHERE custody.custody_plan_id = NEW.custody_plan_id
      AND custody.mission_id = NEW.mission_id
      AND NEW.participant_index < custody.participant_count
      AND assertion_use.principal_profile_id = NEW.profile_id
      AND assertion_use.assertion_hash = NEW.assertion_sha256
      AND assertion_use.operation = NEW.operation
      AND assertion_use.signed_intent_hash = NEW.operation_intent_sha256
      AND assertion_use.trust_policy_hash = NEW.policy_sha256
      AND assertion_use.scope_grant_hash = NEW.scope_grant_sha256
      AND assertion_use.idempotency_key_hash IS NULL
      AND assertion_use.consumed_at = NEW.committed_at
      AND effect.effect_kind = NEW.operation
      AND effect.effect_id = NEW.authentication_id
      AND effect.recorded_at = NEW.committed_at
      AND NEW.committed_at = custody.committed_at
      AND json_extract(
          custody.custody_plan_json,
          '$.assertion_consumption_order[' || NEW.participant_index || ']'
      ) = NEW.authentication_id
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index || '].role'
      ) = NEW.role
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index
              || '].authentication_id'
      ) = NEW.authentication_id
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index
              || '].authentication_sha256'
      ) = NEW.authentication_sha256
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index || '].profile_id'
      ) = NEW.profile_id
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index || '].issuer'
      ) = NEW.issuer
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index || '].assertion_id'
      ) = NEW.assertion_id
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index
              || '].assertion_sha256'
      ) = NEW.assertion_sha256
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index || '].operation'
      ) = NEW.operation
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index
              || '].operation_intent_sha256'
      ) = NEW.operation_intent_sha256
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index || '].policy_sha256'
      ) = NEW.policy_sha256
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index || '].scope_grant_id'
      ) = NEW.scope_grant_id
      AND json_extract(
          custody.custody_plan_json,
          '$.participant_authentications[' || NEW.participant_index
              || '].scope_grant_sha256'
      ) = NEW.scope_grant_sha256
)
BEGIN
    SELECT RAISE(ABORT, 'execution terminal custody participant is inconsistent');
END;

CREATE TRIGGER execution_terminal_custody_commits_immutable
BEFORE UPDATE ON execution_terminal_custody_commits
BEGIN
    SELECT RAISE(ABORT, 'execution terminal custody commit is immutable');
END;

CREATE TRIGGER execution_terminal_custody_commits_no_delete
BEFORE DELETE ON execution_terminal_custody_commits
BEGIN
    SELECT RAISE(ABORT, 'execution terminal custody commit cannot be deleted');
END;

CREATE TRIGGER execution_terminal_custody_participants_immutable
BEFORE UPDATE ON execution_terminal_custody_participants
BEGIN
    SELECT RAISE(ABORT, 'execution terminal custody participant is immutable');
END;

CREATE TRIGGER execution_terminal_custody_participants_no_delete
BEFORE DELETE ON execution_terminal_custody_participants
BEGIN
    SELECT RAISE(ABORT, 'execution terminal custody participant cannot be deleted');
END;
"""

SCHEMA_V22_ADDITIONS_SQL = """
CREATE TABLE execution_session_authority_commits (
    session_authority_id TEXT PRIMARY KEY
        CHECK (
            length(session_authority_id) = 36
            AND substr(session_authority_id, 1, 4) = 'ESA-'
            AND substr(session_authority_id, 5) NOT GLOB '*[^0-9A-F]*'
        ),
    session_authority_sha256 TEXT NOT NULL UNIQUE,
    mission_id TEXT NOT NULL,
    collaboration_plan_id TEXT NOT NULL,
    collaboration_plan_sha256 TEXT NOT NULL,
    work_item_id TEXT NOT NULL,
    authority_kind TEXT NOT NULL
        CHECK (authority_kind IN ('initial_activation', 'handoff_activation')),
    basis_kind TEXT NOT NULL
        CHECK (basis_kind IN ('activated_plan', 'completed_terminal_custody')),
    basis_id TEXT NOT NULL,
    basis_sha256 TEXT NOT NULL,
    channel_policy_id TEXT NOT NULL,
    channel_policy_sha256 TEXT NOT NULL,
    session_id TEXT NOT NULL UNIQUE,
    session_sha256 TEXT NOT NULL UNIQUE,
    owner_profile_id TEXT NOT NULL,
    owner_epoch INTEGER NOT NULL CHECK (owner_epoch >= 1),
    worker_principal_id TEXT NOT NULL,
    fence_generation INTEGER NOT NULL CHECK (fence_generation >= 1),
    credential_reference_id TEXT NOT NULL UNIQUE,
    credential_sha256 TEXT NOT NULL UNIQUE,
    effective_at TEXT NOT NULL CHECK (length(effective_at) > 0),
    expires_at TEXT NOT NULL CHECK (length(expires_at) > 0),
    authority_json TEXT NOT NULL
        CHECK (
            length(authority_json) > 0
            AND json_valid(authority_json)
            AND json_type(authority_json, '$') = 'object'
        ),
    committed_at TEXT NOT NULL CHECK (length(committed_at) > 0),
    UNIQUE (mission_id, work_item_id, fence_generation),
    CHECK (
        (authority_kind = 'initial_activation'
            AND basis_kind = 'activated_plan'
            AND substr(basis_id, 1, 4) = 'CLP-'
            AND fence_generation = 1)
        OR
        (authority_kind = 'handoff_activation'
            AND basis_kind = 'completed_terminal_custody'
            AND substr(basis_id, 1, 4) = 'ECT-'
            AND fence_generation > 1)
    ),
    CHECK (json_extract(authority_json, '$.session_authority_id') = session_authority_id),
    CHECK (
        json_extract(authority_json, '$.session_authority_sha256')
            = session_authority_sha256
    ),
    CHECK (json_extract(authority_json, '$.authority_kind') = authority_kind),
    CHECK (
        json_extract(authority_json, '$.authorization_basis.basis_kind')
            = basis_kind
    ),
    CHECK (
        json_extract(authority_json, '$.authorization_basis.basis_id')
            = basis_id
    ),
    CHECK (
        json_extract(authority_json, '$.authorization_basis.basis_sha256')
            = basis_sha256
    ),
    CHECK (json_extract(authority_json, '$.session.mission_id') = mission_id),
    CHECK (
        json_extract(authority_json, '$.session.collaboration_plan_id')
            = collaboration_plan_id
    ),
    CHECK (
        json_extract(authority_json, '$.session.collaboration_plan_sha256')
            = collaboration_plan_sha256
    ),
    CHECK (
        json_extract(authority_json, '$.session.work_item_id')
            = work_item_id
    ),
    CHECK (
        json_extract(authority_json, '$.session.channel_policy.channel_policy_id')
            = channel_policy_id
    ),
    CHECK (
        json_extract(authority_json, '$.session.channel_policy.channel_policy_sha256')
            = channel_policy_sha256
    ),
    CHECK (json_extract(authority_json, '$.session.session_id') = session_id),
    CHECK (json_extract(authority_json, '$.session.session_sha256') = session_sha256),
    CHECK (
        json_extract(authority_json, '$.session.owner_profile_id')
            = owner_profile_id
    ),
    CHECK (json_extract(authority_json, '$.session.owner_epoch') = owner_epoch),
    CHECK (
        json_extract(authority_json, '$.session.worker_principal_id')
            = worker_principal_id
    ),
    CHECK (
        json_extract(authority_json, '$.session.fence_generation')
            = fence_generation
    ),
    CHECK (
        json_extract(authority_json, '$.session.credential_reference_id')
            = credential_reference_id
    ),
    CHECK (
        json_extract(authority_json, '$.session.credential_sha256')
            = credential_sha256
    ),
    CHECK (json_extract(authority_json, '$.effective_at') = effective_at),
    CHECK (json_extract(authority_json, '$.expires_at') = expires_at),
    CHECK (
        json_extract(authority_json, '$.authority_status')
            = 'pending_atomic_commit'
    ),
    CHECK (json_extract(authority_json, '$.runtime_effect') = 'none'),
    CHECK (committed_at = effective_at),
    FOREIGN KEY (mission_id)
        REFERENCES missions(mission_id) ON DELETE RESTRICT,
    FOREIGN KEY (collaboration_plan_id)
        REFERENCES collaboration_plan_activations(plan_id) ON DELETE RESTRICT,
    FOREIGN KEY (channel_policy_id)
        REFERENCES execution_channel_policy_commits(channel_policy_id)
        ON DELETE RESTRICT
);

CREATE UNIQUE INDEX execution_session_handoff_basis_identity
ON execution_session_authority_commits (basis_id)
WHERE authority_kind = 'handoff_activation';

CREATE TRIGGER execution_session_authority_basis_guard
BEFORE INSERT ON execution_session_authority_commits
WHEN NOT EXISTS (
    SELECT 1
    FROM execution_channel_policy_commits AS channel
    JOIN collaboration_plan_activations AS activation
      ON activation.plan_id = NEW.collaboration_plan_id
     AND activation.mission_id = NEW.mission_id
     AND activation.plan_content_sha256 = NEW.collaboration_plan_sha256
    WHERE channel.channel_policy_id = NEW.channel_policy_id
      AND channel.channel_policy_sha256 = NEW.channel_policy_sha256
      AND channel.mission_id = NEW.mission_id
      AND channel.plan_id = NEW.collaboration_plan_id
      AND channel.plan_content_sha256 = NEW.collaboration_plan_sha256
      AND (
        (
          NEW.authority_kind = 'initial_activation'
          AND NEW.basis_id = activation.plan_id
          AND NEW.basis_sha256 = activation.plan_content_sha256
          AND NEW.owner_profile_id = NEW.worker_principal_id
          AND EXISTS (
              SELECT 1
              FROM json_each(activation.plan_json, '$.work_items') AS item
              WHERE json_extract(item.value, '$.work_item_id') = NEW.work_item_id
                AND json_extract(item.value, '$.owner_profile_id')
                    = NEW.owner_profile_id
          )
        )
        OR
        (
          NEW.authority_kind = 'handoff_activation'
          AND EXISTS (
              SELECT 1
              FROM execution_terminal_custody_commits AS custody
              WHERE custody.custody_plan_id = NEW.basis_id
                AND custody.custody_plan_sha256 = NEW.basis_sha256
                AND custody.mission_id = NEW.mission_id
                AND custody.work_item_id = NEW.work_item_id
                AND custody.terminal_kind = 'completed'
                AND custody.target_session_disposition
                    = 'eligible_after_atomic_commit'
                AND custody.request_authentication_id = json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.request_authentication.authentication_id'
                )
                AND custody.request_authentication_sha256 = json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.request_authentication.authentication_sha256'
                )
                AND custody.transfer_request_id = json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.request_authentication.transfer_request.request_id'
                )
                AND custody.transfer_request_sha256 = json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.request_authentication.transfer_request.request_sha256'
                )
                AND NEW.session_id = json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.request_authentication.transfer_request.target_session.session_id'
                )
                AND NEW.session_sha256 = json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.request_authentication.transfer_request.target_session.session_sha256'
                )
                AND json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.source_session.session_id'
                ) = json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.request_authentication.transfer_request.source_session.session_id'
                )
                AND json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.source_session.session_sha256'
                ) = json_extract(
                    NEW.authority_json,
                    '$.activation_evidence.request_authentication.transfer_request.source_session.session_sha256'
                )
          )
        )
      )
)
BEGIN
    SELECT RAISE(ABORT, 'execution session authority basis is inconsistent');
END;

CREATE TRIGGER execution_session_authority_commits_immutable
BEFORE UPDATE ON execution_session_authority_commits
BEGIN
    SELECT RAISE(ABORT, 'execution session authority commit is immutable');
END;

CREATE TRIGGER execution_session_authority_commits_no_delete
BEFORE DELETE ON execution_session_authority_commits
BEGIN
    SELECT RAISE(ABORT, 'execution session authority commit cannot be deleted');
END;
"""

