SCHEMA_V39_ADDITIONS_SQL = """
CREATE TABLE provider_evidence_repository_ingest_authentications (
    authentication_id TEXT PRIMARY KEY
        CHECK (
            length(authentication_id) = 36
            AND substr(authentication_id, 1, 4) = 'ERI-'
            AND substr(authentication_id, 5) NOT GLOB '*[^0-9A-F]*'
        ),
    authentication_sha256 TEXT NOT NULL UNIQUE,
    mission_id TEXT NOT NULL,
    ingest_request_id TEXT NOT NULL,
    ingest_request_sha256 TEXT NOT NULL,
    ingest_receipt_id TEXT NOT NULL,
    ingest_receipt_sha256 TEXT NOT NULL,
    lifecycle_policy_id TEXT NOT NULL,
    lifecycle_policy_sha256 TEXT NOT NULL,
    source_report_authentication_id TEXT NOT NULL,
    source_report_authentication_sha256 TEXT NOT NULL,
    source_report_custody_id TEXT NOT NULL,
    source_report_custody_sha256 TEXT NOT NULL,
    source_attempt_id TEXT NOT NULL,
    source_acknowledgement_id TEXT NOT NULL,
    source_acknowledgement_sha256 TEXT NOT NULL,
    source_dispatch_id TEXT NOT NULL,
    source_dispatch_sha256 TEXT NOT NULL,
    content_address TEXT NOT NULL,
    evidence_size_bytes INTEGER NOT NULL CHECK (evidence_size_bytes BETWEEN 1 AND 16777216),
    repository_id TEXT NOT NULL,
    object_version_id TEXT NOT NULL,
    outcome TEXT NOT NULL
        CHECK (outcome IN ('accepted', 'already_exists_same_digest', 'rejected', 'failed')),
    repository_principal_subject TEXT NOT NULL,
    repository_principal_profile_id TEXT NOT NULL,
    repository_issuer TEXT NOT NULL,
    repository_assertion_id TEXT NOT NULL,
    repository_assertion_sha256 TEXT NOT NULL,
    authenticated_at TEXT NOT NULL CHECK (length(authenticated_at) > 0),
    authentication_json TEXT NOT NULL CHECK (
        length(CAST(authentication_json AS BLOB)) BETWEEN 1 AND 1048576
        AND json_valid(authentication_json)
        AND json_type(authentication_json, '$') = 'object'
    ),
    authentication_status TEXT NOT NULL
        CHECK (authentication_status = 'authenticated_expected_repository_principal'),
    lifecycle_policy_status TEXT NOT NULL
        CHECK (lifecycle_policy_status = 'prepared_policy_bound_not_activated'),
    repository_control_status TEXT NOT NULL
        CHECK (repository_control_status = 'provider_assertions_not_independently_verified'),
    external_effect_status TEXT NOT NULL
        CHECK (external_effect_status = 'authenticated_report_unverified_effect'),
    dedicated_identity_status TEXT NOT NULL CHECK (
        dedicated_identity_status =
            'expected_identity_authenticated_deployment_dedication_unverified'
    ),
    evidence_custody_status TEXT NOT NULL CHECK (evidence_custody_status = 'provider_report_only'),
    raw_evidence_in_contract INTEGER NOT NULL CHECK (raw_evidence_in_contract = 0),
    runtime_effect TEXT NOT NULL CHECK (runtime_effect = 'none'),
    UNIQUE (repository_issuer, repository_assertion_id),
    FOREIGN KEY (mission_id) REFERENCES missions(mission_id) ON DELETE RESTRICT,
    FOREIGN KEY (source_report_authentication_id)
        REFERENCES executor_invocation_provider_report_authentications(report_authentication_id)
        ON DELETE RESTRICT,
    FOREIGN KEY (repository_issuer, repository_assertion_id, mission_id)
        REFERENCES principal_assertion_uses(issuer, assertion_id, mission_id) ON DELETE RESTRICT
) STRICT;

CREATE INDEX provider_evidence_repository_ingest_authentications_mission
ON provider_evidence_repository_ingest_authentications(
    mission_id, authenticated_at, authentication_id
);

CREATE TRIGGER provider_evidence_repository_ingest_authentication_guard
BEFORE INSERT ON provider_evidence_repository_ingest_authentications
WHEN json_type(NEW.authentication_json, '$.schema_version') IS NOT 'integer'
OR json_extract(NEW.authentication_json, '$.schema_version') IS NOT 1
""" + "\n".join(
    f"OR json_type(NEW.authentication_json, '$.{path}') IS NOT '{kind}'\n"
    f"OR json_extract(NEW.authentication_json, '$.{path}') IS NOT NEW.{column}"
    for column, path, kind in _REPOSITORY_INGEST_JSON_PROJECTIONS
) + """
OR NOT EXISTS (
    SELECT 1
    FROM executor_invocation_provider_report_authentications AS source
    JOIN executor_invocation_provider_reports AS report
      ON report.report_custody_id = source.report_custody_id
     AND report.report_custody_sha256 = source.report_custody_sha256
     AND report.mission_id = source.mission_id
    JOIN executor_dispatch_reservations AS reservation
      ON reservation.authentication_id = report.authentication_id
     AND reservation.mission_id = NEW.mission_id
     AND reservation.dispatch_id = NEW.source_dispatch_id
     AND reservation.dispatch_sha256 = NEW.source_dispatch_sha256
    JOIN principal_assertion_uses AS repository_use
      ON repository_use.issuer = NEW.repository_issuer
     AND repository_use.assertion_id = NEW.repository_assertion_id
     AND repository_use.mission_id = NEW.mission_id
     AND repository_use.subject = NEW.repository_principal_subject
     AND repository_use.principal_profile_id = NEW.repository_principal_profile_id
     AND repository_use.assertion_hash = NEW.repository_assertion_sha256
     AND repository_use.operation = 'sunderkey.evidence.repository.acknowledge.v1'
     AND repository_use.consumed_at = NEW.authenticated_at
     AND repository_use.key_id = json_extract(
         NEW.authentication_json, '$.repository_attestor.key_id'
     )
     AND repository_use.key_hash = json_extract(
         NEW.authentication_json, '$.repository_attestor.key_sha256'
     )
     AND repository_use.audience = json_extract(
         NEW.authentication_json, '$.repository_attestor.audience'
     )
     AND repository_use.store_id = json_extract(
         NEW.authentication_json, '$.repository_attestor.store_id'
     )
     AND repository_use.signed_intent_hash = json_extract(
         NEW.authentication_json, '$.repository_attestor.operation_intent_sha256'
     )
     AND repository_use.scope_grant_hash = json_extract(
         NEW.authentication_json, '$.repository_attestor.scope_grant_sha256'
     )
     AND repository_use.trust_policy_id = json_extract(
         NEW.authentication_json, '$.repository_attestor.policy_id'
     )
     AND json_type(NEW.authentication_json, '$.repository_attestor.policy_version') = 'integer'
     AND repository_use.trust_policy_version = json_extract(
         NEW.authentication_json, '$.repository_attestor.policy_version'
     )
     AND repository_use.trust_policy_hash = json_extract(
         NEW.authentication_json, '$.repository_attestor.policy_sha256'
     )
     AND repository_use.expires_at = json_extract(
         NEW.authentication_json, '$.repository_attestor.expires_at'
     )
    JOIN mission_scope_grants AS repository_scope
      ON repository_scope.grant_hash = repository_use.scope_grant_hash
     AND repository_scope.mission_id = NEW.mission_id
     AND repository_scope.grant_id = json_extract(
         NEW.authentication_json, '$.repository_attestor.scope_grant_id'
     )
    JOIN principal_assertion_effects AS repository_effect
      ON repository_effect.issuer = repository_use.issuer
     AND repository_effect.assertion_id = repository_use.assertion_id
     AND repository_effect.mission_id = NEW.mission_id
     AND repository_effect.effect_index = 1
     AND repository_effect.effect_kind = repository_use.operation
     AND repository_effect.effect_id = NEW.authentication_id
     AND repository_effect.recorded_at = NEW.authenticated_at
    WHERE source.report_authentication_id = NEW.source_report_authentication_id
      AND source.report_authentication_sha256 = NEW.source_report_authentication_sha256
      AND source.mission_id = NEW.mission_id
      AND source.report_custody_id = NEW.source_report_custody_id
      AND source.report_custody_sha256 = NEW.source_report_custody_sha256
      AND source.attempt_id = NEW.source_attempt_id
      AND source.acknowledgement_id = NEW.source_acknowledgement_id
      AND source.acknowledgement_sha256 = NEW.source_acknowledgement_sha256
      AND report.dispatch_id = NEW.source_dispatch_id
      AND report.dispatch_sha256 = NEW.source_dispatch_sha256
      AND source.authenticated_at <= NEW.authenticated_at
      AND json_extract(repository_use.assertion_json, '$.issued_at') >= json_extract(
          NEW.authentication_json, '$.ingest_receipt.responded_at'
      )
      AND unixepoch(repository_scope.expires_at) - unixepoch(repository_scope.not_before)
          <= json_extract(
              NEW.authentication_json, '$.lifecycle_policy.access.maximum_access_seconds'
          )
      AND 1 = (
          SELECT COUNT(*) FROM principal_assertion_effects AS effects
          WHERE effects.issuer = repository_use.issuer
            AND effects.assertion_id = repository_use.assertion_id
      )
)
BEGIN
    SELECT RAISE(ABORT, 'repository ingest authentication is inconsistent');
END;

CREATE TRIGGER provider_evidence_repository_ingest_authentications_immutable
BEFORE UPDATE ON provider_evidence_repository_ingest_authentications
BEGIN
    SELECT RAISE(ABORT, 'repository ingest authentication is immutable');
END;

CREATE TRIGGER provider_evidence_repository_ingest_authentications_no_delete
BEFORE DELETE ON provider_evidence_repository_ingest_authentications
BEGIN
    SELECT RAISE(ABORT, 'repository ingest authentication cannot be deleted');
END;
"""


def _split_schema_statements(value: str) -> tuple[str, ...]:
    statements: list[str] = []
    pending: list[str] = []
    for line in value.splitlines():
        pending.append(line)
        candidate = "\n".join(pending).strip()
        if candidate and sqlite3.complete_statement(candidate):
            statements.append(candidate)
            pending = []
    if "\n".join(pending).strip():
        raise RuntimeError("Schema SQL contains an incomplete statement")
    return tuple(statements)


