def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        allow_nan=False,
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    )


def sha256_text(value: str) -> str:
    return HASH_PREFIX + hashlib.sha256(value.encode("ascii")).hexdigest()


def work_item_transition_id(
    issuer: str,
    assertion_id: str,
) -> str:
    """Derive one stable transition ID from an assertion identity."""

    digest = hashlib.sha256(
        canonical_json(
            {
                "assertion_id": assertion_id,
                "domain": "sunderkey.work-item-transition.v1",
                "issuer": issuer,
            }
        ).encode("ascii")
    ).hexdigest()
    return "WLT-" + digest[:32].upper()


def work_recovery_request_id(
    issuer: str,
    assertion_id: str,
) -> str:
    """Derive one stable recovery request ID."""

    digest = hashlib.sha256(
        canonical_json(
            {
                "assertion_id": assertion_id,
                "domain": "sunderkey.work-recovery-request.v1",
                "issuer": issuer,
            }
        ).encode("ascii")
    ).hexdigest()
    return "WRQ-" + digest[:32].upper()


def work_recovery_decision_id(
    issuer: str,
    assertion_id: str,
) -> str:
    """Derive one stable recovery decision ID."""

    digest = hashlib.sha256(
        canonical_json(
            {
                "assertion_id": assertion_id,
                "domain": "sunderkey.work-recovery-decision.v1",
                "issuer": issuer,
            }
        ).encode("ascii")
    ).hexdigest()
    return "WRD-" + digest[:32].upper()


def work_cancellation_id(
    issuer: str,
    assertion_id: str,
) -> str:
    """Derive one stable work cancellation ID."""

    digest = hashlib.sha256(
        canonical_json(
            {
                "assertion_id": assertion_id,
                "domain": "sunderkey.work-cancellation.v1",
                "issuer": issuer,
            }
        ).encode("ascii")
    ).hexdigest()
    return "WCN-" + digest[:32].upper()


def work_handoff_id(
    owner_issuer: str,
    owner_assertion_id: str,
    candidate_issuer: str,
    candidate_assertion_id: str,
) -> str:
    """Derive one stable work handoff ID from both assertions."""

    digest = hashlib.sha256(
        canonical_json(
            {
                "candidate_assertion_id": candidate_assertion_id,
                "candidate_issuer": candidate_issuer,
                "domain": "sunderkey.work-handoff.v1",
                "owner_assertion_id": owner_assertion_id,
                "owner_issuer": owner_issuer,
            }
        ).encode("ascii")
    ).hexdigest()
    return "WHF-" + digest[:32].upper()


def event_append_batch_hash(
    events: Iterable[MissionEvent],
) -> str:
    pending = tuple(events)
    if not pending:
        raise StoreError("At least one event is required")
    if any(not isinstance(event, MissionEvent) for event in pending):
        raise StoreError(
            "events must contain only validated MissionEvent objects"
        )
    normalized = tuple(
        MissionEvent.from_dict(event.to_dict())
        for event in pending
    )
    return sha256_text(
        canonical_json(
            {
                "domain": "sunderkey.event-append-batch.v1",
                "events": [
                    event.to_dict()
                    for event in normalized
                ],
                "schema_version": 1,
            }
        )
    )


