def mission_stop_request_hash(
    operation_intent: dict[str, Any],
) -> str:
    intent = validate_operation_intent(
        PrincipalOperation.MISSION_STOP,
        operation_intent,
    )
    request = dict(intent)
    request.pop("idempotency_key_sha256")
    return sha256_text(canonical_json(request))


def control_event_id(
    kind: str,
    subject_id: str,
    key_hash: str,
    request_hash: str,
    collision_index: int,
) -> str:
    if kind not in {"AUTH", "BLOCK", "STOP", "REVOKE"}:
        raise StoreError(f"Unsupported service event kind: {kind}")
    if (
        not isinstance(collision_index, int)
        or isinstance(collision_index, bool)
        or collision_index < 0
        or collision_index > CONTROL_EVENT_COLLISION_INDEX_MAX
    ):
        raise StoreError("Mission control event collision index is invalid")
    material = canonical_json(
        {
            "kind": kind,
            "subject_id": subject_id,
            "key_hash": key_hash,
            "request_hash": request_hash,
            "collision_index": collision_index,
        }
    )
    digest = hashlib.sha256(material.encode("ascii")).hexdigest().upper()
    return f"EVT-{kind}-C{collision_index:08X}-{digest}"


def is_service_event_id(event_id: str) -> bool:
    if event_id.startswith(("EVT-STOP-", "EVT-REVOKE-")):
        return True
    for kind in ("AUTH", "BLOCK"):
        prefix = f"EVT-{kind}-C"
        index_end = len(prefix) + 8
        if (
            len(event_id) == index_end + 65
            and event_id.startswith(prefix)
            and event_id[index_end] == "-"
            and all(
                character in "0123456789ABCDEF"
                for character in event_id[len(prefix):index_end]
            )
            and all(
                character in "0123456789ABCDEF"
                for character in event_id[index_end + 1:]
            )
        ):
            return True
    return False


def allocate_control_event_id(
    ledger: EventLedger,
    *,
    kind: str,
    subject_id: str,
    key_hash: str,
    request_hash: str,
) -> str:
    existing = {event.event_id for event in ledger.events}
    if len(existing) > CONTROL_EVENT_COLLISION_INDEX_MAX:
        raise StoreError("Mission control event collision space is exhausted")
    for collision_index in range(len(existing) + 1):
        candidate = control_event_id(
            kind,
            subject_id,
            key_hash,
            request_hash,
            collision_index,
        )
        if candidate not in existing:
            return candidate
    raise StoreError("Could not allocate a mission control event ID")


def utc_now() -> datetime:
    return datetime.now(UTC)


def format_timestamp(value: datetime) -> str:
    if value.tzinfo is None or value.utcoffset() is None:
        raise StoreError("Store timestamps must include a timezone")
    normalized = value.astimezone(UTC).replace(microsecond=0)
    return normalized.isoformat().replace("+00:00", "Z")


def parse_timestamp(value: str, label: str) -> datetime:
    candidate = value[:-1] + "+00:00" if value.endswith("Z") else value
    try:
        parsed = datetime.fromisoformat(candidate)
    except (TypeError, ValueError) as exc:
        raise StoreIntegrityError(f"{label} is not a valid timestamp") from exc
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise StoreIntegrityError(f"{label} must include a timezone")
    return parsed


