class MissionStore:
    """SQLite store that replays every event through the in-memory ledger."""

    def __init__(
        self,
        path: str | Path,
        *,
        clock: Callable[[], datetime] = utc_now,
        busy_timeout_ms: int = 5000,
    ) -> None:
        self.path = Path(path).resolve()
        self._clock = clock
        if (
            not isinstance(busy_timeout_ms, int)
            or isinstance(busy_timeout_ms, bool)
            or busy_timeout_ms < 1
            or busy_timeout_ms > 120000
        ):
            raise StoreError("busy_timeout_ms must be between 1 and 120000")
        self._busy_timeout_ms = busy_timeout_ms

    def initialize(self) -> None:
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            connection = sqlite3.connect(self.path, isolation_level=None)
            try:
                self._configure(connection)
                application_id = int(
                    connection.execute("PRAGMA application_id").fetchone()[0]
                )
                user_version = int(
                    connection.execute("PRAGMA user_version").fetchone()[0]
                )
                existing_objects = {
                    str(row[0])
                    for row in connection.execute(
                        """
                        SELECT name FROM sqlite_master
                        WHERE name NOT LIKE 'sqlite_%'
                        """
                    ).fetchall()
                }
                is_new = application_id == 0 and user_version == 0
                if is_new and existing_objects:
                    raise StoreIntegrityError(
                        "Unmarked database already contains unrelated objects"
                    )
                if not is_new and application_id != APPLICATION_ID:
                    raise StoreIntegrityError(
                        "Database markers do not match a SUNDERKEY mission store"
                    )
                if not is_new and user_version not in {
                    LEGACY_SCHEMA_VERSION,
                    MISSION_CONTROL_SCHEMA_VERSION,
                    AUTHENTICATED_PRINCIPAL_SCHEMA_VERSION,
                    SCOPE_REVOCATION_SCHEMA_VERSION,
                    EVENT_AUTHENTICATION_SCHEMA_VERSION,
                    APPROVAL_DECISION_AUTHENTICATION_SCHEMA_VERSION,
                    APPROVAL_SUBMISSION_AUTHENTICATION_SCHEMA_VERSION,
                    APPROVAL_REVOCATION_AUTHENTICATION_SCHEMA_VERSION,
                    SIMULATION_AUTHENTICATION_SCHEMA_VERSION,
                    MISSION_CREATION_AUTHENTICATION_SCHEMA_VERSION,
                    COLLABORATION_ACTIVATION_SCHEMA_VERSION,
                    WORK_ITEM_CLAIM_SCHEMA_VERSION,
                    WORK_ITEM_RECOVERY_SCHEMA_VERSION,
                    WORK_ITEM_CANCELLATION_SCHEMA_VERSION,
                    EXECUTION_TERMINAL_CUSTODY_SCHEMA_VERSION,
                    EXECUTION_SESSION_AUTHORITY_SCHEMA_VERSION,
                    EXECUTION_SESSION_STATE_SCHEMA_VERSION,
                    EXECUTOR_DISPATCH_CUSTODY_SCHEMA_VERSION,
                    EXECUTOR_DELIVERY_CLAIM_CUSTODY_SCHEMA_VERSION,
                    EXECUTOR_INVOCATION_ATTEMPT_CUSTODY_SCHEMA_VERSION,
                    EXECUTOR_PROVIDER_REPORT_CUSTODY_SCHEMA_VERSION,
                    EXECUTOR_PROVIDER_REPORT_AUTHENTICATION_SCHEMA_VERSION,
                    COLLABORATION_PLAN_REPLACEMENT_SCHEMA_VERSION,
                    AUTHENTICATED_PLAN_REPLACEMENT_SCHEMA_VERSION,
                    AUTHENTICATED_MODEL_EXECUTION_SCHEMA_VERSION,
                    AUTHENTICATED_EXPERT_REVIEW_SCHEMA_VERSION,
                    AUTHENTICATED_ACTION_ADMISSION_SCHEMA_VERSION,
                    AUTHENTICATED_ACTION_EXECUTION_SCHEMA_VERSION,
                    TARGET_HEALTH_GATE_SCHEMA_VERSION,
                    ACTION_TARGET_HEALTH_GATE_USE_SCHEMA_VERSION,
                    ACTION_EXECUTION_TARGET_HEALTH_GATE_SCHEMA_VERSION,
                    PLAN_REPLACEMENT_REVIEWER_ADMISSION_SCHEMA_VERSION,
                    SCHEMA_VERSION,
                }:
                    raise StoreIntegrityError(
                        "Database schema version is not supported"
                    )
                if not is_new:
                    version = self._require_schema(connection)
                    if version >= MISSION_CONTROL_SCHEMA_VERSION:
                        self._require_safe_journal_mode(connection)
                    return
                self._set_safe_journal_mode(connection)
                self._prepare_v29_schema_rebuild(connection)
                try:
                    connection.execute("BEGIN IMMEDIATE")
                    for statement in SCHEMA_STATEMENTS:
                        connection.execute(statement)
                    connection.execute(f"PRAGMA application_id = {APPLICATION_ID}")
                    connection.execute(f"PRAGMA user_version = {SCHEMA_VERSION}")
                    connection.execute(
                        "INSERT INTO store_metadata(key, value) VALUES (?, ?)",
                        ("schema_version", str(SCHEMA_VERSION)),
                    )
                    self._insert_store_identity(
                        connection,
                        created_at=format_timestamp(self._clock()),
                    )
                    from .action_target_health_gate_use import (
                        insert_action_execution_target_health_gate_legacy_baseline,
                        insert_action_target_health_gate_legacy_baseline,
                    )

                    insert_action_target_health_gate_legacy_baseline(connection)
                    insert_action_execution_target_health_gate_legacy_baseline(
                        connection
                    )
                    self._foreign_key_check(connection)
                    connection.commit()
                except Exception:
                    connection.rollback()
                    raise
                finally:
                    self._restore_v29_schema_rebuild_pragmas(connection)
            except Exception:
                connection.rollback()
                raise
            finally:
                connection.close()
        except (OSError, sqlite3.Error) as exc:
            raise StoreError(f"Could not initialize mission store: {self.path}") from exc

    def migrate(
        self,
        registry: ExpertRegistry,
        backup_destination: str | Path,
    ) -> MigrationReport:
        target = Path(backup_destination).resolve()
        if target == self.path:
            raise StoreError("Migration backup must differ from the source store")
        if not self.path.is_file():
            raise StoreError(f"Mission store does not exist: {self.path}")

        connection: sqlite3.Connection | None = None
        temporary_backup: Path | None = None
        try:
            connection = sqlite3.connect(
                self.path.as_uri() + "?mode=rw",
                timeout=self._busy_timeout_ms / 1000,
                isolation_level=None,
                uri=True,
            )
            self._configure(connection)
            version = self._require_schema(connection, allow_legacy=True)
            if version == SCHEMA_VERSION:
                self._require_safe_journal_mode(connection)
                self._quick_check(connection)
                self._foreign_key_check(connection)
                self._verify_connection(
                    connection,
                    registry,
                    schema_version=SCHEMA_VERSION,
                    require_current_action_sources=False,
                )
                return MigrationReport(
                    status="already_current",
                    source_version=SCHEMA_VERSION,
                    target_version=SCHEMA_VERSION,
                    store=str(self.path),
                    backup=None,
                )
            if target.exists():
                raise StoreConflictError(
                    f"Migration backup already exists: {target}"
                )
            journal_mode = self._journal_mode(connection)
            if version >= MISSION_CONTROL_SCHEMA_VERSION:
                self._require_safe_journal_mode(connection)
            elif (
                journal_mode == "wal"
                and not sqlite_wal_reset_fix_available()
            ):
                raise StoreError(
                    "Offline migration of a WAL mission store requires "
                    "SQLite 3.51.3 or later, or a fixed backport such as "
                    "3.50.7 or 3.44.6; current SQLite is "
                    f"{sqlite3.sqlite_version}"
                )
            target.parent.mkdir(parents=True, exist_ok=True)
            descriptor, temporary_name = tempfile.mkstemp(
                prefix=f".{target.name}.",
                suffix=".migration.tmp",
                dir=target.parent,
            )
            os.close(descriptor)
            temporary_backup = Path(temporary_name)

            connection.execute("BEGIN IMMEDIATE")
            try:
                locked_version = self._require_schema(
                    connection,
                    allow_legacy=True,
                )
                if locked_version != version:
                    raise StoreConflictError(
                        "Mission store changed before migration lock acquisition"
                    )
                if version >= MISSION_CONTROL_SCHEMA_VERSION:
                    self._require_safe_journal_mode(connection)
                self._quick_check(connection)
                self._foreign_key_check(connection)
                self._verify_connection(
                    connection,
                    registry,
                    schema_version=version,
                    require_current_action_sources=False,
                )
                source_data_version = int(
                    connection.execute(
                        "PRAGMA data_version"
                    ).fetchone()[0]
                )

                backup_source = sqlite3.connect(
                    self.path.as_uri() + "?mode=ro",
                    uri=True,
                )
                destination = sqlite3.connect(temporary_backup)
                try:
                    backup_source.backup(destination)
                finally:
                    destination.close()
                    backup_source.close()
                backup_store = MissionStore(
                    temporary_backup,
                    busy_timeout_ms=self._busy_timeout_ms,
                )
                backup_connection = sqlite3.connect(
                    temporary_backup.as_uri() + "?mode=rw",
                    timeout=self._busy_timeout_ms / 1000,
                    isolation_level=None,
                    uri=True,
                )
                try:
                    backup_store._configure(backup_connection)
                    backup_store._require_schema(
                        backup_connection,
                        allow_legacy=True,
                    )
                    if version == LEGACY_SCHEMA_VERSION:
                        backup_store._set_safe_journal_mode(
                            backup_connection,
                        )
                    else:
                        backup_store._require_safe_journal_mode(
                            backup_connection,
                        )
                finally:
                    backup_connection.close()
                backup_store.verify_store(registry)
                try:
                    os.link(temporary_backup, target)
                except FileExistsError as exc:
                    raise StoreConflictError(
                        f"Migration backup already exists: {target}"
                    ) from exc

            finally:
                connection.rollback()

            if version == LEGACY_SCHEMA_VERSION:
                self._set_safe_journal_mode(connection)
            else:
                self._require_safe_journal_mode(connection)
            self._prepare_v29_schema_rebuild(connection)
            try:
                connection.execute("BEGIN IMMEDIATE")
                locked_version = self._require_schema(
                    connection,
                    allow_legacy=True,
                )
                if locked_version != version:
                    raise StoreConflictError(
                        "Mission store changed before schema migration"
                    )
                if int(
                    connection.execute(
                        "PRAGMA data_version"
                    ).fetchone()[0]
                ) != source_data_version:
                    raise StoreConflictError(
                        "Mission store changed after migration backup"
                    )
                self._quick_check(connection)
                self._foreign_key_check(connection)
                self._verify_connection(
                    connection,
                    registry,
                    schema_version=version,
                    require_current_action_sources=False,
                )
                if version == LEGACY_SCHEMA_VERSION:
                    for statement in SCHEMA_V2_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    connection.execute(
                        """
                        INSERT INTO mission_controls(
                            mission_id,
                            state,
                            version
                        )
                        SELECT mission_id, 'active', 1
                        FROM missions
                        ORDER BY mission_id
                        """
                    )
                if version < AUTHENTICATED_PRINCIPAL_SCHEMA_VERSION:
                    for statement in SCHEMA_V3_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    store_id = self._insert_store_identity(
                        connection,
                        created_at=format_timestamp(self._clock()),
                    )
                    mission_rows = connection.execute(
                        "SELECT * FROM missions ORDER BY mission_id"
                    ).fetchall()
                    principal_baseline_at = format_timestamp(
                        self._clock()
                    )
                    for mission_row in mission_rows:
                        mission_id = str(mission_row["mission_id"])
                        baseline = self._historical_principal_baseline(
                            connection,
                            mission_id=mission_id,
                            source_schema_version=version,
                        )
                        self._insert_principal_ledger(
                            connection,
                            mission_id=mission_id,
                            store_id=store_id,
                            baseline_kind="historical_v2",
                            baseline=baseline,
                            created_at=principal_baseline_at,
                        )
                else:
                    store_id = str(
                        self._store_identity_row(connection)["store_id"]
                    )
                    mission_rows = connection.execute(
                        "SELECT * FROM missions ORDER BY mission_id"
                    ).fetchall()
                if version < SCOPE_REVOCATION_SCHEMA_VERSION:
                    for statement in SCHEMA_V4_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    revocation_baseline_at = format_timestamp(
                        self._clock()
                    )
                    for mission_row in mission_rows:
                        mission_id = str(
                            mission_row["mission_id"]
                        )
                        self._insert_scope_revocation_baseline(
                            connection,
                            mission_id=mission_id,
                            store_id=store_id,
                            source_schema_version=version,
                            created_at=revocation_baseline_at,
                        )
                if version < EVENT_AUTHENTICATION_SCHEMA_VERSION:
                    undefined_event_uses = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation = ?
                            """,
                            (EVENT_APPEND_EFFECT_KIND,),
                        ).fetchone()[0]
                    )
                    undefined_event_effects = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind = ?
                            """,
                            (EVENT_APPEND_EFFECT_KIND,),
                        ).fetchone()[0]
                    )
                    if (
                        undefined_event_uses
                        or undefined_event_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v5 event-append provenance cannot "
                            "be promoted"
                        )
                    for statement in SCHEMA_V5_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    event_baseline_at = format_timestamp(
                        self._clock()
                    )
                    for mission_row in mission_rows:
                        mission_id = str(
                            mission_row["mission_id"]
                        )
                        self._insert_event_authentication_baseline(
                            connection,
                            mission_id=mission_id,
                            store_id=store_id,
                            source_schema_version=version,
                            created_at=event_baseline_at,
                        )
                if (
                    version
                    < APPROVAL_DECISION_AUTHENTICATION_SCHEMA_VERSION
                ):
                    undefined_decision_uses = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN (?, ?)
                            """,
                            (
                                APPROVAL_APPROVE_EFFECT_KIND,
                                APPROVAL_DENY_EFFECT_KIND,
                            ),
                        ).fetchone()[0]
                    )
                    undefined_decision_effects = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN (?, ?)
                            """,
                            (
                                APPROVAL_APPROVE_EFFECT_KIND,
                                APPROVAL_DENY_EFFECT_KIND,
                            ),
                        ).fetchone()[0]
                    )
                    if (
                        undefined_decision_uses
                        or undefined_decision_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v6 approval-decision provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V6_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    decision_baseline_at = format_timestamp(
                        self._clock()
                    )
                    for mission_row in mission_rows:
                        mission_id = str(
                            mission_row["mission_id"]
                        )
                        self._insert_approval_decision_authentication_baseline(
                            connection,
                            mission_id=mission_id,
                            store_id=store_id,
                            source_schema_version=version,
                            created_at=decision_baseline_at,
                        )
                if (
                    version
                    < APPROVAL_SUBMISSION_AUTHENTICATION_SCHEMA_VERSION
                ):
                    undefined_submission_uses = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation = ?
                            """,
                            (
                                APPROVAL_SUBMIT_EFFECT_KIND,
                            ),
                        ).fetchone()[0]
                    )
                    undefined_submission_effects = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind = ?
                            """,
                            (
                                APPROVAL_SUBMIT_EFFECT_KIND,
                            ),
                        ).fetchone()[0]
                    )
                    if (
                        undefined_submission_uses
                        or undefined_submission_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v7 approval-submission provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V7_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    submission_baseline_at = format_timestamp(
                        self._clock()
                    )
                    for mission_row in mission_rows:
                        mission_id = str(
                            mission_row["mission_id"]
                        )
                        self._insert_approval_submission_authentication_baseline(
                            connection,
                            mission_id=mission_id,
                            store_id=store_id,
                            source_schema_version=version,
                            created_at=submission_baseline_at,
                        )
                if (
                    version
                    < APPROVAL_REVOCATION_AUTHENTICATION_SCHEMA_VERSION
                ):
                    undefined_revocation_uses = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation = ?
                            """,
                            (APPROVAL_REVOKE_EFFECT_KIND,),
                        ).fetchone()[0]
                    )
                    undefined_revocation_effects = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind = ?
                            """,
                            (APPROVAL_REVOKE_EFFECT_KIND,),
                        ).fetchone()[0]
                    )
                    if (
                        undefined_revocation_uses
                        or undefined_revocation_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v8 approval-revocation provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V8_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    revocation_baseline_at = format_timestamp(
                        self._clock()
                    )
                    for mission_row in mission_rows:
                        mission_id = str(
                            mission_row["mission_id"]
                        )
                        self._insert_approval_revocation_authentication_baseline(
                            connection,
                            mission_id=mission_id,
                            store_id=store_id,
                            source_schema_version=version,
                            created_at=revocation_baseline_at,
                        )
                if version < SIMULATION_AUTHENTICATION_SCHEMA_VERSION:
                    undefined_simulation_uses = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation = ?
                            """,
                            (SIMULATION_RUN_EFFECT_KIND,),
                        ).fetchone()[0]
                    )
                    undefined_simulation_effects = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind = ?
                            """,
                            (SIMULATION_RUN_EFFECT_KIND,),
                        ).fetchone()[0]
                    )
                    if (
                        undefined_simulation_uses
                        or undefined_simulation_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v9 simulation provenance cannot "
                            "be promoted"
                        )
                    for statement in SCHEMA_V9_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    simulation_baseline_at = format_timestamp(
                        self._clock()
                    )
                    for mission_row in mission_rows:
                        mission_id = str(
                            mission_row["mission_id"]
                        )
                        self._insert_simulation_authentication_baseline(
                            connection,
                            mission_id=mission_id,
                            store_id=store_id,
                            source_schema_version=version,
                            created_at=simulation_baseline_at,
                        )
                if (
                    version
                    < MISSION_CREATION_AUTHENTICATION_SCHEMA_VERSION
                ):
                    undefined_creation_uses = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation = ?
                            """,
                            (MISSION_CREATE_EFFECT_KIND,),
                        ).fetchone()[0]
                    )
                    undefined_creation_effects = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind = ?
                            """,
                            (MISSION_CREATE_EFFECT_KIND,),
                        ).fetchone()[0]
                    )
                    if (
                        undefined_creation_uses
                        or undefined_creation_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v10 mission-creation provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V10_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    creation_provenance_at = format_timestamp(
                        self._clock()
                    )
                    for mission_row in mission_rows:
                        self._insert_mission_creation_provenance(
                            connection,
                            mission_id=str(
                                mission_row["mission_id"]
                            ),
                            store_id=store_id,
                            mission_context_hash=str(
                                mission_row["context_hash"]
                            ),
                            provenance_kind="historical_pre_v10",
                            source_schema_version=version,
                            recorded_at=creation_provenance_at,
                        )
                if version < COLLABORATION_ACTIVATION_SCHEMA_VERSION:
                    undefined_activation_uses = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation = ?
                            """,
                            (
                                COLLABORATION_ACTIVATE_EFFECT_KIND,
                            ),
                        ).fetchone()[0]
                    )
                    undefined_activation_effects = int(
                        connection.execute(
                            """
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind = ?
                            """,
                            (
                                COLLABORATION_ACTIVATE_EFFECT_KIND,
                            ),
                        ).fetchone()[0]
                    )
                    if (
                        undefined_activation_uses
                        or undefined_activation_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v11 collaboration activation "
                            "provenance cannot be promoted"
                        )
                    for statement in SCHEMA_V11_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < WORK_ITEM_CLAIM_SCHEMA_VERSION:
                    placeholders = ", ".join(
                        "?" for _ in WORK_ITEM_EFFECT_KINDS
                    )
                    operations = tuple(
                        sorted(WORK_ITEM_EFFECT_KINDS)
                    )
                    undefined_work_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_work_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if (
                        undefined_work_uses
                        or undefined_work_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v12 work item transition provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V12_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < WORK_ITEM_RECOVERY_SCHEMA_VERSION:
                    placeholders = ", ".join(
                        "?" for _ in WORK_RECOVERY_EFFECT_KINDS
                    )
                    operations = tuple(
                        sorted(WORK_RECOVERY_EFFECT_KINDS)
                    )
                    undefined_recovery_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_recovery_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if (
                        undefined_recovery_uses
                        or undefined_recovery_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v13 work recovery provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V13_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < WORK_ITEM_CANCELLATION_SCHEMA_VERSION:
                    operations = tuple(
                        sorted(WORK_CANCELLATION_EFFECT_KINDS)
                    )
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_cancellation_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_cancellation_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if (
                        undefined_cancellation_uses
                        or undefined_cancellation_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v14 work cancellation provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V14_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < WORK_ITEM_HANDOFF_SCHEMA_VERSION:
                    operations = tuple(
                        sorted(WORK_HANDOFF_EFFECT_KINDS)
                    )
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_handoff_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_handoff_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if (
                        undefined_handoff_uses
                        or undefined_handoff_effects
                    ):
                        raise StoreIntegrityError(
                            "Pre-v15 work handoff provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V15_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < COLLABORATION_MISSION_POLICY_SCHEMA_VERSION:
                    operations = (
                        COLLABORATION_POLICY_CONTROL_APPROVE_EFFECT_KIND,
                        COLLABORATION_POLICY_OWNER_AUTHORIZE_EFFECT_KIND,
                    )
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_policy_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_policy_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if undefined_policy_uses or undefined_policy_effects:
                        raise StoreIntegrityError(
                            "Pre-v16 collaboration mission policy provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V16_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < COLLABORATION_OWNERSHIP_SCHEMA_VERSION:
                    operations = tuple(
                        sorted(COLLABORATION_OWNERSHIP_EFFECT_KINDS)
                    )
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_ownership_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_ownership_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if undefined_ownership_uses or undefined_ownership_effects:
                        raise StoreIntegrityError(
                            "Pre-v17 collaboration ownership provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V17_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < COLLABORATION_OWNERSHIP_REVOCATION_SCHEMA_VERSION:
                    for statement in SCHEMA_V18_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < COLLABORATION_OWNERSHIP_PRIVILEGED_SCHEMA_VERSION:
                    for statement in SCHEMA_V19_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < EXECUTION_CHANNEL_POLICY_SCHEMA_VERSION:
                    operations = (
                        EXECUTION_CHANNEL_POLICY_CONTROL_APPROVE_EFFECT_KIND,
                        EXECUTION_CHANNEL_POLICY_OWNER_AUTHORIZE_EFFECT_KIND,
                    )
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_channel_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_channel_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if undefined_channel_uses or undefined_channel_effects:
                        raise StoreIntegrityError(
                            "Pre-v20 execution channel policy provenance "
                            "cannot be promoted"
                        )
                    for statement in SCHEMA_V20_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < EXECUTION_TERMINAL_CUSTODY_SCHEMA_VERSION:
                    operations = (
                        PrincipalOperation.EXECUTION_TRANSFER_REQUEST_AUTHORIZE.value,
                        PrincipalOperation.EXECUTION_TRANSFER_ACKNOWLEDGE.value,
                        PrincipalOperation.EXECUTION_TIMEOUT_RESOLVE.value,
                    )
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_terminal_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_terminal_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if undefined_terminal_uses or undefined_terminal_effects:
                        raise StoreIntegrityError(
                            "Pre-v21 execution terminal provenance cannot be promoted"
                        )
                    for statement in SCHEMA_V21_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < EXECUTION_SESSION_AUTHORITY_SCHEMA_VERSION:
                    for statement in SCHEMA_V22_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < EXECUTION_SESSION_STATE_SCHEMA_VERSION:
                    operations = tuple(sorted(EXECUTION_SESSION_EFFECT_KINDS))
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_session_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_session_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if undefined_session_uses or undefined_session_effects:
                        raise StoreIntegrityError(
                            "Pre-v23 execution session provenance cannot be promoted"
                        )
                    for statement in SCHEMA_V23_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < EXECUTOR_DISPATCH_CUSTODY_SCHEMA_VERSION:
                    operations = tuple(sorted(EXECUTOR_DISPATCH_EFFECT_KINDS))
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_dispatch_uses = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_uses
                            WHERE operation IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_dispatch_effects = int(
                        connection.execute(
                            f"""
                            SELECT COUNT(*)
                            FROM principal_assertion_effects
                            WHERE effect_kind IN ({placeholders})
                            """,
                            operations,
                        ).fetchone()[0]
                    )
                    if undefined_dispatch_uses or undefined_dispatch_effects:
                        raise StoreIntegrityError(
                            "Pre-v24 executor dispatch provenance cannot be promoted"
                        )
                    for statement in SCHEMA_V24_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < EXECUTOR_DELIVERY_CLAIM_CUSTODY_SCHEMA_VERSION:
                    for statement in SCHEMA_V25_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < EXECUTOR_INVOCATION_ATTEMPT_CUSTODY_SCHEMA_VERSION:
                    for statement in SCHEMA_V26_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < EXECUTOR_PROVIDER_REPORT_CUSTODY_SCHEMA_VERSION:
                    for statement in SCHEMA_V27_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if (
                    version
                    < EXECUTOR_PROVIDER_REPORT_AUTHENTICATION_SCHEMA_VERSION
                ):
                    for statement in SCHEMA_V28_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < COLLABORATION_PLAN_REPLACEMENT_SCHEMA_VERSION:
                    for statement in SCHEMA_V29_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < AUTHENTICATED_PLAN_REPLACEMENT_SCHEMA_VERSION:
                    prior_replacements = int(
                        connection.execute(
                            "SELECT COUNT(*) FROM collaboration_plan_replacement_commits"
                        ).fetchone()[0]
                    )
                    if prior_replacements:
                        raise StoreIntegrityError(
                            "Pre-v30 plan replacements have no signed authority custody"
                        )
                    for statement in SCHEMA_V30_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < AUTHENTICATED_MODEL_EXECUTION_SCHEMA_VERSION:
                    for statement in SCHEMA_V31_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < AUTHENTICATED_EXPERT_REVIEW_SCHEMA_VERSION:
                    operations = tuple(sorted(AUTHENTICATED_EXPERT_REVIEW_EFFECT_KINDS))
                    placeholders = ", ".join("?" for _ in operations)
                    undefined_review_uses = int(
                        connection.execute(
                            f"SELECT COUNT(*) FROM principal_assertion_uses "
                            f"WHERE operation IN ({placeholders})",
                            operations,
                        ).fetchone()[0]
                    )
                    undefined_review_effects = int(
                        connection.execute(
                            f"SELECT COUNT(*) FROM principal_assertion_effects "
                            f"WHERE effect_kind IN ({placeholders})",
                            operations,
                        ).fetchone()[0]
                    )
                    if undefined_review_uses or undefined_review_effects:
                        raise StoreIntegrityError(
                            "Pre-v32 expert review provenance cannot be promoted"
                        )
                    for statement in SCHEMA_V32_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < AUTHENTICATED_ACTION_ADMISSION_SCHEMA_VERSION:
                    for statement in SCHEMA_V33_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < AUTHENTICATED_ACTION_EXECUTION_SCHEMA_VERSION:
                    for statement in SCHEMA_V34_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < TARGET_HEALTH_GATE_SCHEMA_VERSION:
                    for statement in SCHEMA_V35_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < ACTION_TARGET_HEALTH_GATE_USE_SCHEMA_VERSION:
                    for statement in SCHEMA_V36_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    from .action_target_health_gate_use import (
                        insert_action_target_health_gate_legacy_baseline,
                    )

                    insert_action_target_health_gate_legacy_baseline(connection)
                if (
                    version
                    < ACTION_EXECUTION_TARGET_HEALTH_GATE_SCHEMA_VERSION
                ):
                    for statement in SCHEMA_V37_ADDITION_STATEMENTS:
                        connection.execute(statement)
                    from .action_target_health_gate_use import (
                        insert_action_execution_target_health_gate_legacy_baseline,
                    )

                    insert_action_execution_target_health_gate_legacy_baseline(
                        connection
                    )
                if version < PLAN_REPLACEMENT_REVIEWER_ADMISSION_SCHEMA_VERSION:
                    unsigned = connection.execute(
                        "SELECT COUNT(*) FROM collaboration_plan_replacement_commits "
                        "AS replacement LEFT JOIN "
                        "collaboration_plan_replacement_authentications AS authority "
                        "ON authority.preflight_id = replacement.preflight_id "
                        "WHERE authority.preflight_id IS NULL"
                    ).fetchone()[0]
                    if unsigned:
                        raise StoreIntegrityError(
                            "Unsigned replacement history cannot acquire signed runtime "
                            "custody. Preserve the historical store and its backup."
                        )
                    operations = tuple(sorted(PLAN_REPLACEMENT_REVIEWER_ADMISSION_EFFECT_KINDS))
                    placeholders = ", ".join("?" for _ in operations)
                    for table, column in (
                        ("principal_assertion_uses", "operation"),
                        ("principal_assertion_effects", "effect_kind"),
                    ):
                        if connection.execute(
                            f"SELECT COUNT(*) FROM {table} WHERE {column} "
                            f"IN ({placeholders})", operations
                        ).fetchone()[0]:
                            raise StoreIntegrityError(
                                "Pre-v38 reviewer admission provenance cannot be promoted"
                            )
                    for statement in SCHEMA_V38_ADDITION_STATEMENTS:
                        connection.execute(statement)
                if version < PROVIDER_EVIDENCE_REPOSITORY_AUTHENTICATION_SCHEMA_VERSION:
                    operation = PrincipalOperation.EVIDENCE_REPOSITORY_ACKNOWLEDGE.value
                    for table, column in (
                        ("principal_assertion_uses", "operation"),
                        ("principal_assertion_effects", "effect_kind"),
                    ):
                        if connection.execute(
                            f"SELECT COUNT(*) FROM {table} WHERE {column} = ?",
                            (operation,),
                        ).fetchone()[0]:
                            raise StoreIntegrityError(
                                "Pre-v39 repository acknowledgement provenance cannot "
                                "acquire durable ingest custody. Preserve the historical "
                                "store and its verified backup."
                            )
                    for statement in SCHEMA_V39_ADDITION_STATEMENTS:
                        connection.execute(statement)
                connection.execute(
                    """
                    UPDATE store_metadata
                    SET value = ?
                    WHERE key = 'schema_version' AND value = ?
                    """,
                    (
                        str(SCHEMA_VERSION),
                        str(version),
                    ),
                )
                if connection.execute("SELECT changes()").fetchone()[0] != 1:
                    raise StoreIntegrityError(
                        "Source schema metadata changed during migration"
                    )
                connection.execute(
                    f"PRAGMA user_version = {SCHEMA_VERSION}"
                )
                self._require_schema(connection)
                self._quick_check(connection)
                self._foreign_key_check(connection)
                self._verify_connection(
                    connection,
                    registry,
                    schema_version=SCHEMA_VERSION,
                    require_current_action_sources=False,
                )
                connection.commit()
            except Exception:
                connection.rollback()
                raise
            finally:
                self._restore_v29_schema_rebuild_pragmas(connection)
            return MigrationReport(
                status="migrated",
                source_version=version,
                target_version=SCHEMA_VERSION,
                store=str(self.path),
                backup=str(target),
            )
        except StoreError:
            raise
        except (OSError, sqlite3.Error) as exc:
            raise StoreError(
                f"Could not migrate mission store: {self.path}"
            ) from exc
        finally:
            if connection is not None:
                connection.close()
            if temporary_backup is not None:
                with suppress(OSError):
                    temporary_backup.unlink(missing_ok=True)

    def _insert_store_identity(
        self,
        connection: sqlite3.Connection,
        *,
        created_at: str,
    ) -> str:
        store_id = "STR-" + secrets.token_hex(16).upper()
        connection.execute(
            """
            INSERT INTO store_identity(
                singleton_id,
                store_id,
                created_at
            ) VALUES (1, ?, ?)
            """,
            (store_id, created_at),
        )
        return store_id

    def _store_identity_row(
        self,
        connection: sqlite3.Connection,
    ) -> sqlite3.Row:
        rows = connection.execute(
            "SELECT * FROM store_identity ORDER BY singleton_id"
        ).fetchall()
        if len(rows) != 1:
            raise StoreIntegrityError(
                "Mission store must contain exactly one store identity"
            )
        return rows[0]

    def _empty_principal_baseline(
        self,
        *,
        mission_id: str,
        mission_context_hash: str,
    ) -> dict[str, Any]:
        return {
            "schema": "sunderkey.mission-principal-ledger-baseline.v1",
            "baseline_kind": "empty",
            "authentication_status": "no_authenticated_principal_uses",
            "mission_id": mission_id,
            "mission_context_hash": mission_context_hash,
        }

    def _historical_table_summary(
        self,
        rows: Iterable[sqlite3.Row],
    ) -> dict[str, Any]:
        row_hashes = [
            sha256_text(
                canonical_json(dict(row))
            )
            for row in rows
        ]
        return {
            "count": len(row_hashes),
            "row_hashes": row_hashes,
            "root_hash": sha256_text(canonical_json(row_hashes)),
        }

    def _historical_scope_revocation_summary(
        self,
        connection: sqlite3.Connection,
        *,
        mission_id: str,
    ) -> dict[str, Any]:
        rows = connection.execute(
            """
            SELECT
                grant_hash,
                issuer,
                grant_id,
                mission_id,
                accepted_at,
                revoked_at,
                revocation_reason
            FROM mission_scope_grants
            WHERE mission_id = ? AND revoked_at IS NOT NULL
            ORDER BY issuer, grant_id
            """,
            (mission_id,),
        ).fetchall()
        return self._historical_table_summary(rows)

    def _scope_revocation_baseline(
        self,
        connection: sqlite3.Connection,
        *,
        mission_id: str,
        source_schema_version: int,
    ) -> tuple[str, dict[str, Any]]:
        mission_row = connection.execute(
            """
            SELECT context_hash FROM missions
            WHERE mission_id = ?
            """,
            (mission_id,),
        ).fetchone()
        if mission_row is None:
            raise StoreIntegrityError(
                "Scope revocation baseline mission is missing"
            )
        historical = self._historical_scope_revocation_summary(
            connection,
            mission_id=mission_id,
        )
        historical_count = int(historical["count"])
        baseline_kind = (
            "historical_v3"
            if (
                source_schema_version
                == AUTHENTICATED_PRINCIPAL_SCHEMA_VERSION
                and historical_count > 0
            )
            else "empty"
        )
        if historical_count > 0 and baseline_kind != "historical_v3":
            raise StoreIntegrityError(
                "Only schema version 3 can supply historical scope "
                "revocations"
            )
        provenance_status = (
            "historical_v3_scope_revocations_not_signature_verified"
            if baseline_kind == "historical_v3"
            else "no_pre_v4_scope_revocations"
        )
        return baseline_kind, {
            "schema": "sunderkey.mission-scope-revocation-baseline.v1",
            "baseline_kind": baseline_kind,
            "provenance_status": provenance_status,
            "mission_id": mission_id,
            "mission_context_hash": str(mission_row["context_hash"]),
            "source_schema_version": source_schema_version,
            "historical_revocations": historical,
        }

    def _insert_scope_revocation_baseline(
        self,
        connection: sqlite3.Connection,
        *,
        mission_id: str,
        store_id: str,
        source_schema_version: int,
        created_at: str,
    ) -> None:
        baseline_kind, baseline = self._scope_revocation_baseline(
            connection,
            mission_id=mission_id,
            source_schema_version=source_schema_version,
        )
        baseline_json = canonical_json(baseline)
        baseline_hash = sha256_text(baseline_json)
        baseline_root_hash = scope_revocation_baseline_root_hash(
            mission_id,
            baseline_hash,
        )
        historical = baseline["historical_revocations"]
        connection.execute(
            """
            INSERT INTO mission_scope_revocation_baselines(
                mission_id,
                store_id,
                baseline_kind,
                source_schema_version,
                baseline_json,
                baseline_hash,
                historical_revocation_count,
                historical_revocation_root_hash,
                baseline_root_hash,
                head_hash,
                signed_revocation_count,
                created_at,
                updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?)
            """,
            (
                mission_id,
                store_id,
                baseline_kind,
                source_schema_version,
                baseline_json,
                baseline_hash,
                int(historical["count"]),
                str(historical["root_hash"]),
                baseline_root_hash,
                baseline_root_hash,
                created_at,
                created_at,
            ),
        )

    def _event_authentication_baseline(
        self,
        connection: sqlite3.Connection,
        *,
        mission_id: str,
        source_schema_version: int,
    ) -> tuple[str, dict[str, Any]]:
        row = connection.execute(
            """
            SELECT context_hash, revision, head_hash
            FROM missions
            WHERE mission_id = ?
            """,
            (mission_id,),
        ).fetchone()
        if row is None:
            raise StoreIntegrityError(
                "Event authentication baseline mission is missing"
            )
        event_count = int(
            connection.execute(
                """
                SELECT COUNT(*) FROM mission_events
                WHERE mission_id = ?
                """,
                (mission_id,),
            ).fetchone()[0]
        )
        revision = int(row["revision"])
        if revision != event_count:
            raise StoreIntegrityError(
                "Event authentication baseline revision does not "
                "match the event count"
            )
        baseline_kind = (
            "historical_pre_v5"
            if event_count > 0
            else "empty"
        )
        if (
            baseline_kind == "historical_pre_v5"
            and source_schema_version
            >= EVENT_AUTHENTICATION_SCHEMA_VERSION
        ):
            raise StoreIntegrityError(
                "Fresh schema v5 missions cannot create historical "
                "event baselines"
            )
        provenance_status = (
            "historical_events_not_event_append_authenticated"
            if baseline_kind == "historical_pre_v5"
            else "no_pre_v5_events"
        )
        return baseline_kind, {
            "schema": (
                "sunderkey.mission-event-authentication-baseline.v1"
            ),
            "baseline_kind": baseline_kind,
            "provenance_status": provenance_status,
            "mission_id": mission_id,
            "mission_context_hash": str(row["context_hash"]),
            "source_schema_version": source_schema_version,
            "event_count": event_count,
            "event_head_hash": str(row["head_hash"]),
        }

    def _insert_event_authentication_baseline(
        self,
        connection: sqlite3.Connection,
        *,
        mission_id: str,
        store_id: str,
        source_schema_version: int,
        created_at: str,
    ) -> None:
        baseline_kind, baseline = (
            self._event_authentication_baseline(
                connection,
                mission_id=mission_id,
                source_schema_version=source_schema_version,
            )
        )
        baseline_json = canonical_json(baseline)
        baseline_hash = sha256_text(baseline_json)
        baseline_root_hash = (
            event_authentication_baseline_root_hash(
                mission_id,
                baseline_hash,
            )
        )
        connection.execute(
            """
            INSERT INTO mission_event_authentication_baselines(
                mission_id,
                store_id,
                baseline_kind,
                source_schema_version,
                mission_context_hash,
                baseline_json,
                baseline_hash,
                baseline_root_hash,
                event_count,
                event_head_hash,
                created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                mission_id,
                store_id,
                baseline_kind,
                source_schema_version,
                str(baseline["mission_context_hash"]),
                baseline_json,
                baseline_hash,
                baseline_root_hash,
                int(baseline["event_count"]),
                str(baseline["event_head_hash"]),
                created_at,
            ),
        )

    @staticmethod
    def _approval_record_at_decision(
        row: sqlite3.Row,
    ) -> dict[str, Any]:
        status = str(row["status"])
        if status == "denied":
            decision_state = "denied"
        elif status in {"approved", "consumed", "revoked"}:
            decision_state = "approved"
        else:
            raise StoreIntegrityError(
                "Approval has no durable decision state"
            )
        return {
            "schema_version": 1,
            "approval_id": str(row["approval_id"]),
            "mission_id": str(row["mission_id"]),
            "proposal_id": str(row["proposal_id"]),
            "proposal_hash": str(row["proposal_hash"]),
            "proposer_profile_id": str(
                row["proposer_profile_id"]
            ),
            "executor_profile_id": str(
                row["executor_profile_id"]
            ),
            "action_tier": str(row["action_tier"]),
            "scope_reference": str(row["scope_reference"]),
            "purpose": str(row["purpose"]),
            "state": decision_state,
            "submitted_at": str(row["submitted_at"]),
            "review_expires_at": str(
                row["review_expires_at"]
            ),
            "version": 2,
            "decision_actor_profile_id": str(
                row["decision_actor_profile_id"]
            ),
            "decision_at": str(row["decision_at"]),
            "decision_code": str(row["decision_code"]),
            "decision_reason": str(row["decision_reason"]),
            "decision_event_id": str(row["decision_event_id"]),
            "authorization_event_id": (
                str(row["authorization_event_id"])
                if row["authorization_event_id"] is not None
                else None
            ),
            "authorization_expires_at": (
                str(row["authorization_expires_at"])
                if row["authorization_expires_at"] is not None
                else None
            ),
            "simulation_id": None,
        }

    @staticmethod
    def _approval_decision_effect_kind(
        row: sqlite3.Row,
    ) -> str:
        return (
            APPROVAL_DENY_EFFECT_KIND
            if str(row["status"]) == "denied"
            else APPROVAL_APPROVE_EFFECT_KIND
        )

    def _approval_decision_projection(
        self,
        connection: sqlite3.Connection,
        row: sqlite3.Row,
    ) -> dict[str, Any]:
        decision_event_id = row["decision_event_id"]
        if decision_event_id is None:
            raise StoreIntegrityError(
                "Approval decision event is missing"
            )
        event = connection.execute(
            """
            SELECT event_json
            FROM mission_events
            WHERE mission_id = ? AND event_id = ?
            """,
            (row["mission_id"], decision_event_id),
        ).fetchone()
        if event is None:
            raise StoreIntegrityError(
                "Approval decision event is missing from the ledger"
            )
        try:
            raw_event = json.loads(str(event["event_json"]))
            decision_event = MissionEvent.from_dict(
                raw_event
            ).to_dict()
        except (json.JSONDecodeError, KeyError, TypeError, ValueError) as exc:
            raise StoreIntegrityError(
                "Approval decision event is invalid"
            ) from exc
        if canonical_json(decision_event) != event["event_json"]:
            raise StoreIntegrityError(
                "Approval decision event is not canonical"
            )
        return {
            "approval_id": str(row["approval_id"]),
            "approval_record": self._approval_record_at_decision(
                row
            ),
            "decision_event": decision_event,
            "decision_request_sha256": str(
                row["decision_request_hash"]
            ),
            "idempotency_key_sha256": str(
                row["decision_key_hash"]
            ),
            "operation": self._approval_decision_effect_kind(
                row
            ),
        }

    def _approval_decision_authentication_baseline(
        self,
        connection: sqlite3.Connection,
        *,
        mission_id: str,
        source_schema_version: int,
    ) -> tuple[str, dict[str, Any]]:
        mission_row = connection.execute(
            """
            SELECT context_hash, revision, head_hash
            FROM missions
            WHERE mission_id = ?
            """,
            (mission_id,),
        ).fetchone()
        if mission_row is None:
            raise StoreIntegrityError(
                "Approval decision authentication baseline mission "
                "is missing"
            )
        event_count = int(
            connection.execute(
                """
                SELECT COUNT(*)
                FROM mission_events
                WHERE mission_id = ?
                """,
                (mission_id,),
            ).fetchone()[0]
        )
        if int(mission_row["revision"]) != event_count:
            raise StoreIntegrityError(
                "Approval decision authentication baseline revision "
                "does not match the event count"
            )
        approval_rows = connection.execute(
            """
            SELECT *
            FROM approval_queue
            WHERE mission_id = ?
              AND status IN (
                  'approved',
                  'denied',
                  'consumed',
                  'revoked'
              )
            ORDER BY approval_id
            """,
            (mission_id,),
        ).fetchall()
        decisions = [
            self._approval_decision_projection(
                connection,
                row,
            )
            for row in approval_rows
        ]
        baseline_kind = (
            "historical_pre_v6"
            if event_count > 0 or decisions
            else "empty"
        )
        if (
            baseline_kind == "historical_pre_v6"
            and source_schema_version
            >= APPROVAL_DECISION_AUTHENTICATION_SCHEMA_VERSION
        ):
            raise StoreIntegrityError(
                "Fresh schema v6 missions cannot create historical "
                "approval decision baselines"
            )
        return baseline_kind, {
            "schema": (
                "sunderkey.mission-approval-decision-"
                "authentication-baseline.v1"
            ),
            "baseline_kind": baseline_kind,
            "provenance_status": (
                "historical_decisions_not_principal_authenticated"
                if decisions
                else (
                    "historical_event_prefix_no_decisions"
                    if event_count > 0
                    else "no_pre_v6_events_or_decisions"
                )
            ),
            "mission_id": mission_id,
            "mission_context_hash": str(
                mission_row["context_hash"]
            ),
            "source_schema_version": source_schema_version,
            "event_count": event_count,
            "event_head_hash": str(mission_row["head_hash"]),
            "historical_decisions": decisions,
            "historical_decision_root_hash": (
                approval_decision_history_root_hash(decisions)
            ),
        }

