    @staticmethod
    def _approval_record_at_submission(
        row: sqlite3.Row,
    ) -> dict[str, Any]:
        return {
            "schema_version": 1,
            "approval_id": str(row["approval_id"]),
            "mission_id": str(row["mission_id"]),
            "proposal_id": str(row["proposal_id"]),
            "proposal_hash": str(row["proposal_hash"]),
            "proposer_profile_id": str(
                row["proposer_profile_id"]
            ),
            "executor_profile_id": str(
                row["executor_profile_id"]
            ),
            "action_tier": str(row["action_tier"]),
            "scope_reference": str(row["scope_reference"]),
            "purpose": str(row["purpose"]),
            "state": "pending",
            "submitted_at": str(row["submitted_at"]),
            "review_expires_at": str(
                row["review_expires_at"]
            ),
            "version": 1,
            "decision_actor_profile_id": None,
            "decision_at": None,
            "decision_code": None,
            "decision_reason": None,
            "decision_event_id": None,
            "authorization_event_id": None,
            "authorization_expires_at": None,
            "simulation_id": None,
        }

    def _approval_submission_projection(
        self,
        connection: sqlite3.Connection,
        row: sqlite3.Row,
    ) -> dict[str, Any]:
        event = connection.execute(
            """
            SELECT *
            FROM mission_events
            WHERE mission_id = ? AND event_id = ?
            """,
            (row["mission_id"], row["proposal_id"]),
        ).fetchone()
        if event is None:
            raise StoreIntegrityError(
                "Approval submission proposal is missing from the ledger"
            )
        try:
            raw_event = json.loads(str(event["event_json"]))
            proposal_event = MissionEvent.from_dict(
                raw_event
            ).to_dict()
        except (
            json.JSONDecodeError,
            KeyError,
            TypeError,
            ValueError,
        ) as exc:
            raise StoreIntegrityError(
                "Approval submission proposal event is invalid"
            ) from exc
        if canonical_json(proposal_event) != event["event_json"]:
            raise StoreIntegrityError(
                "Approval submission proposal event is not canonical"
            )
        return {
            "approval_id": str(row["approval_id"]),
            "approval_record": self._approval_record_at_submission(
                row
            ),
            "submit_request_sha256": str(
                row["submit_request_hash"]
            ),
            "idempotency_key_sha256": str(
                row["submit_key_hash"]
            ),
            "proposal_event": proposal_event,
            "proposal_sequence": int(event["sequence"]),
            "proposal_entry_hash": str(event["entry_hash"]),
            "proposal_stored_at": str(event["stored_at"]),
        }

