    def _approval_revocation_projection(
        self,
        connection: sqlite3.Connection,
        row: sqlite3.Row,
    ) -> dict[str, Any]:
        approval = connection.execute(
            """
            SELECT *
            FROM approval_queue
            WHERE mission_id = ? AND approval_id = ?
            """,
            (row["mission_id"], row["approval_id"]),
        ).fetchone()
        event = connection.execute(
            """
            SELECT event_json
            FROM mission_events
            WHERE mission_id = ? AND event_id = ?
            """,
            (row["mission_id"], row["revocation_event_id"]),
        ).fetchone()
        if approval is None or event is None:
            raise StoreIntegrityError(
                "Approval revocation projection is incomplete"
            )
        try:
            raw_event = json.loads(str(event["event_json"]))
            revocation_event = MissionEvent.from_dict(
                raw_event
            ).to_dict()
        except (
            json.JSONDecodeError,
            KeyError,
            TypeError,
            ValueError,
        ) as exc:
            raise StoreIntegrityError(
                "Approval revocation event is invalid"
            ) from exc
        if canonical_json(revocation_event) != event["event_json"]:
            raise StoreIntegrityError(
                "Approval revocation event is not canonical"
            )
        return {
            "approval_id": str(row["approval_id"]),
            "approval_record": self._approval_record_at_revocation(
                approval
            ),
            "revocation_record": (
                self._approval_revocation_record_from_row(row)
            ),
            "revocation_event": revocation_event,
            "revocation_request_sha256": str(
                row["request_hash"]
            ),
            "idempotency_key_sha256": str(row["key_hash"]),
            "operation": APPROVAL_REVOKE_EFFECT_KIND,
        }

    def _approval_revocation_authentication_baseline(
        self,
        connection: sqlite3.Connection,
        *,
        mission_id: str,
        source_schema_version: int,
    ) -> tuple[str, dict[str, Any]]:
        mission_row = connection.execute(
            """
            SELECT context_hash, revision, head_hash
            FROM missions
            WHERE mission_id = ?
            """,
            (mission_id,),
        ).fetchone()
        if mission_row is None:
            raise StoreIntegrityError(
                "Approval revocation authentication baseline mission "
                "is missing"
            )
        event_count = int(
            connection.execute(
                """
                SELECT COUNT(*)
                FROM mission_events
                WHERE mission_id = ?
                """,
                (mission_id,),
            ).fetchone()[0]
        )
        if int(mission_row["revision"]) != event_count:
            raise StoreIntegrityError(
                "Approval revocation authentication baseline revision "
                "does not match the event count"
            )
        revocation_rows = connection.execute(
            """
            SELECT *
            FROM approval_revocations
            WHERE mission_id = ?
            ORDER BY approval_id
            """,
            (mission_id,),
        ).fetchall()
        revocations = [
            self._approval_revocation_projection(
                connection,
                row,
            )
            for row in revocation_rows
        ]
        baseline_kind = (
            "historical_pre_v8"
            if event_count > 0 or revocations
            else "empty"
        )
        if (
            baseline_kind == "historical_pre_v8"
            and source_schema_version
            >= APPROVAL_REVOCATION_AUTHENTICATION_SCHEMA_VERSION
        ):
            raise StoreIntegrityError(
                "Fresh schema v8 missions cannot create historical "
                "approval revocation baselines"
            )
        return baseline_kind, {
            "schema": (
                "sunderkey.mission-approval-revocation-"
                "authentication-baseline.v1"
            ),
            "baseline_kind": baseline_kind,
            "provenance_status": (
                "historical_revocations_not_principal_authenticated"
                if revocations
                else (
                    "historical_event_prefix_no_revocations"
                    if event_count > 0
                    else "no_pre_v8_events_or_revocations"
                )
            ),
            "mission_id": mission_id,
            "mission_context_hash": str(
                mission_row["context_hash"]
            ),
            "source_schema_version": source_schema_version,
            "event_count": event_count,
            "event_head_hash": str(mission_row["head_hash"]),
            "historical_revocations": revocations,
            "historical_revocation_root_hash": (
                approval_revocation_history_root_hash(revocations)
            ),
        }

